import random,sys
random.seed(int(sys.argv[1]))
classes=["TPV","SKY","ATT","GST","TOFF","PPS","OSC","IMU","DEVICE","RTCM2","RTCM3","AIS","VERSION","DEVICES","WATCH","ERROR"]
c=random.choice(classes)
def num():
